// Helper para clasificar e iconizar categorías de gastos en condominios
const getCategoryIconComponent = (catName) => {
  const c = (catName || '').toLowerCase();
  if (c.includes('básico') || c.includes('basico') || c.includes('luz') || c.includes('agua') || c.includes('consumo')) return Zap;
  if (c.includes('mantenci') || c.includes('portón') || c.includes('porton') || c.includes('bomba') || c.includes('ascensor')) return Wrench;
  if (c.includes('aseo') || c.includes('verde') || c.includes('jard') || c.includes('piscina')) return Sparkles;
  if (c.includes('sueldo') || c.includes('previs') || c.includes('personal') || c.includes('conserj')) return Users;
  if (c.includes('administra') || c.includes('seguro')) return Shield;
  if (c.includes('reserva')) return Landmark;
  if (c.includes('reparaci') || c.includes('imprevisto') || c.includes('urgencia')) return AlertTriangle;
  return Receipt;
};

// Agrupador ordenado de gastos por categoría con subtotales
const groupExpensesByCategory = (expensesList) => {
  const map = {};
  const priorityOrder = [
    'servicios básicos',
    'servicios basicos',
    'mantención',
    'mantencion',
    'aseo',
    'sueldos',
    'administración',
    'administracion',
    'reparaciones',
    'reserva',
    'fondo de reserva'
  ];

  (expensesList || []).forEach(exp => {
    let cat = exp.category;
    if (exp.fundSource === 'fondo_reserva') {
      cat = 'Fondo de Reserva (Art. 14)';
    } else if (!cat || !cat.trim()) {
      cat = 'Gastos Operacionales Generales';
    }
    if (!map[cat]) {
      map[cat] = {
        name: cat,
        expenses: [],
        total: 0,
        paidTotal: 0,
        unbackedCount: 0,
        unapprovedCount: 0
      };
    }
    const amt = parseFloat(exp.amount) || 0;
    map[cat].expenses.push(exp);
    map[cat].total += amt;
    if (exp.status === 'pagado') map[cat].paidTotal += amt;
    if (!exp.receiptUrl) map[cat].unbackedCount += 1;
    if (!exp.approvedByCommittee) map[cat].unapprovedCount += 1;
  });

  return Object.values(map).sort((a, b) => {
    const aLow = a.name.toLowerCase();
    const bLow = b.name.toLowerCase();
    const idxA = priorityOrder.findIndex(p => aLow.includes(p));
    const idxB = priorityOrder.findIndex(p => bLow.includes(p));
    if (idxA !== -1 && idxB !== -1) return idxA - idxB;
    if (idxA !== -1) return -1;
    if (idxB !== -1) return 1;
    return a.name.localeCompare(b.name);
  });
};

