  // Impresión directa aislada y generación de PDF mediante iframe oculto (inmune a bloqueadores de ventanas emergentes)
  const printDocumentDirectly = (elementId, documentTitle = 'Documento Oficial ARANPRO') => {
    const content = document.getElementById(elementId);
    if (!content) {
      window.print();
      return;
    }

    try {
      let iframe = document.getElementById('aranpro-print-iframe');
      if (!iframe) {
        iframe = document.createElement('iframe');
        iframe.id = 'aranpro-print-iframe';
        iframe.style.position = 'fixed';
        iframe.style.right = '0';
        iframe.style.bottom = '0';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';
        iframe.style.opacity = '0';
        iframe.style.pointerEvents = 'none';
        document.body.appendChild(iframe);
      }

      // Convertir rutas relativas de imágenes a absolutas para asegurar carga en el iframe
      const contentHtml = content.innerHTML.replace(/src="\/brand\//g, `src="${window.location.origin}/brand/`);

      // Copiar hojas de estilos cargadas en el documento principal para renderizado idéntico instantáneo
      const existingStyles = Array.from(document.querySelectorAll('link[rel="stylesheet"], style'))
        .map(el => el.outerHTML)
        .join('\n');

      const doc = iframe.contentWindow || iframe.contentDocument;
      const iDoc = doc.document || doc;
      iDoc.open();
      iDoc.write(`
        <!DOCTYPE html>
        <html lang="es">
          <head>
            <meta charset="utf-8" />
            <title>${documentTitle}</title>
            <script src="https://cdn.tailwindcss.com"></script>
            ${existingStyles}
            <style>
              @page {
                size: letter portrait;
                margin: 5mm 7mm 5mm 7mm;
              }
              * {
                -webkit-print-color-adjust: exact !important;
                print-color-adjust: exact !important;
                color-adjust: exact !important;
                box-sizing: border-box;
              }
              html, body {
                margin: 0 !important;
                padding: 0 !important;
                background: #ffffff !important;
                color: #0f172a;
                font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
                -webkit-font-smoothing: antialiased;
              }
              .no-print { display: none !important; }
              table { width: 100%; border-collapse: collapse; }
              img { max-width: 100%; height: auto; }
              /* Contenedor estricto para asegurar exactamente 1 página sin desbordamiento */
              .print-fit-page {
                max-height: 265mm !important;
                overflow: hidden !important;
                page-break-after: avoid !important;
                page-break-inside: avoid !important;
                padding: 10px 14px !important;
                background: #ffffff !important;
                color: #0f172a !important;
                box-sizing: border-box !important;
              }
            </style>
          </head>
          <body>
            <div class="print-fit-page font-sans text-slate-800">
              ${contentHtml}
            </div>
          </body>
        </html>
      `);
      iDoc.close();

      setTimeout(() => {
        try {
          iframe.contentWindow.focus();
          iframe.contentWindow.print();
        } catch (err) {
          window.print();
        }
      }, 500);
    } catch (e) {
      console.warn('Iframe print error, falling back to window.print()', e);
      window.print();
    }
  };

