  const handleConfirmBatchReconciliation = () => {
    if (!currentCommunity) return;
    const acceptedMovements = parsedBankMovements.filter(m => m.accepted && m.matchedUnit);
    if (acceptedMovements.length === 0) {
      alert('Por favor seleccione al menos un pago reconocido para conciliar.');
      return;
    }

    let newlyApproved = 0;
    let neighborApproved = 0;
    let totalReconciled = 0;

    acceptedMovements.forEach(mvt => {
      totalReconciled += mvt.amount;

      // Mejora 1: Memoria de Pagadores Habituales ("Aprender para la próxima cartola")
      if (mvt.saveAsHabitualPayer && mvt.matchedUnit) {
        const u = mvt.matchedUnit;
        const payerNameToSave = mvt.detectedPayerName?.trim();
        const existingUsers = (u.additionalUsers || []);
        const alreadyHasUser = payerNameToSave && (
          (u.owner && u.owner.toLowerCase() === payerNameToSave.toLowerCase()) ||
          (u.resident && u.resident.toLowerCase() === payerNameToSave.toLowerCase()) ||
          (u.payerName && u.payerName.toLowerCase() === payerNameToSave.toLowerCase()) ||
          existingUsers.some(au => au.name && au.name.toLowerCase() === payerNameToSave.toLowerCase())
        );

        if (payerNameToSave && payerNameToSave.length >= 4 && !alreadyHasUser) {
          const newHabitualUser = {
            id: `payer-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
            name: payerNameToSave,
            role: 'Pagador Habitual (Cartola)',
            rut: mvt.detectedRut || '',
            phone: '',
            email: ''
          };
          updateUnit(currentCommunity.id, u.id, {
            additionalUsers: [...existingUsers, newHabitualUser]
          });
        }
      }

      if (mvt.matchedNeighborColilla) {
        approvePayment(currentCommunity.id, mvt.matchedNeighborColilla.id);
        neighborApproved++;
      } else {
        registerManualPayment(currentCommunity.id, mvt.matchedUnit.id, {
          amount: mvt.amount,
          date: mvt.date,
          payerName: mvt.detectedPayerName || mvt.matchedUnit.payerName || mvt.matchedUnit.resident || mvt.matchedUnit.owner,
          transferNumber: mvt.transferNumber,
          notes: `[Conciliación Cartola ${bankStatementBank}] ${mvt.rawLine}`,
          createReceipt: true,
          mode: 'set'
        });
        newlyApproved++;
      }
    });

    setBankStatementSuccessSummary({
      count: acceptedMovements.length,
      total: totalReconciled,
      neighborCount: neighborApproved,
      newCount: newlyApproved
    });

    setReconciledMovementsForNotification(acceptedMovements);
    setBankStatementStep(3);
  };

