  // Exportar rendición oficial de gastos a CSV con BOM UTF-8
  const exportExpensesToCSV = () => {
    if (!currentCommunity || !currentCommunity.expenses) return;
    const headers = [
      'ID_Gasto', 'Categoria', 'Origen_Fondo', 'Proveedor', 'RUT_Proveedor',
      'Tipo_Documento', 'Numero_Folio', 'Fecha_Emision', 'Monto_CLP',
      'Estado_Pago', 'Fecha_Pago', 'N_Transferencia_o_Ref', 'Metodo_Pago',
      'Visado_Comite', 'Es_Fijo_Recurrente', 'Tiene_Respaldo', 'Glosa_Detalle'
    ];
    
    const rows = (currentCommunity.expenses || []).map(e => [
      `"${e.id || ''}"`,
      `"${e.category || ''}"`,
      `"${e.fundSource === 'fondo_reserva' ? 'Fondo de Reserva' : 'Gasto Ordinario'}"`,
      `"${(e.provider || '').replace(/"/g, '""')}"`,
      `"${e.providerRut || ''}"`,
      `"${e.documentType || ''}"`,
      `"${e.documentNumber || ''}"`,
      `"${e.date || ''}"`,
      parseFloat(e.amount) || 0,
      `"${e.status === 'pagado' ? 'Pagado' : 'Pendiente'}"`,
      `"${e.paymentDate || ''}"`,
      `"${e.paymentReference || ''}"`,
      `"${e.paymentMethod || ''}"`,
      `"${e.approvedByCommittee ? 'SI' : 'NO'}"`,
      `"${e.isRecurring ? 'SI' : 'NO'}"`,
      `"${e.receiptUrl ? 'SI' : 'NO'}"`,
      `"${(e.description || '').replace(/"/g, '""')}"`
    ]);

    const csvContent = '\uFEFF' + [headers.join(';'), ...rows.map(r => r.join(';'))].join('\r\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Rendicion_Gastos_${currentCommunity.name.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

