      <div className="lg:hidden sticky top-0 z-30 bg-[#0F3D2E] text-white px-4 py-2.5 border-b border-[#D4B895]/30 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-2.5 min-w-0">
          <button
            onClick={() => setMobileSidebarOpen(true)}
            className="p-2 bg-white/10 hover:bg-white/20 text-[#D4B895] rounded-xl flex items-center shrink-0"
            aria-label="Abrir panel de navegación"
          >
            <Menu className="w-5 h-5" />
          </button>
          <div className="truncate">
            <span className="text-[10px] font-bold uppercase tracking-wider text-[#D4B895] block leading-tight truncate">
              {currentCommunity?.name || 'Comunidad'}
            </span>
            <span className="text-xs font-black text-white truncate block">
              {activeTabObj.label}
            </span>
          </div>
        </div>

        <div className="flex items-center space-x-1.5 shrink-0">
          <button
            onClick={() => setShowCommitteeReportModal(true)}
            className="px-2.5 py-1.5 bg-[#D4B895] text-[#0F3D2E] text-[11px] font-black rounded-lg flex items-center"
          >
            <Printer className="w-3.5 h-3.5 mr-1" />
            PDF
          </button>
          {onBackToWeb && (
            <button
              onClick={onBackToWeb}
              className="p-1.5 bg-white/10 text-white rounded-lg"
              title="Ir al Sitio Web Público"
            >
              <Globe className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* DRAWER LATERAL DESLIZABLE EN CELULAR / TABLET (< lg) */}
      {mobileSidebarOpen && (
        <div className="fixed inset-0 z-50 lg:hidden flex">
          <div
            className="fixed inset-0 bg-slate-950/60 backdrop-blur-xs"
            onClick={() => setMobileSidebarOpen(false)}
          />
          <div className="relative w-80 max-w-[85vw] h-full z-10 shadow-2xl">
            {renderSidebarContent(true)}
          </div>
        </div>
      )}

      {/* PANEL LATERAL IZQUIERDO FIJO DESDE EL TOPE DE LA PÁGINA EN COMPUTADOR (lg+) */}
      <aside
        className={`hidden lg:block shrink-0 transition-all duration-200 ${
          sidebarCollapsed ? 'w-16' : 'w-60 xl:w-64'
        }`}
      >
        <div className="sticky top-0 h-screen">
          {renderSidebarContent(false)}
        </div>
      </aside>

      {/* COLUMNA DERECHA: BARRA SUPERIOR DEL SOFTWARE + ÁREA DE TRABAJO */}
