                          quotaRoundingMode === 'ceil_1000' && manualTargetQuota === null
                            ? 'bg-[#0F3D2E] text-white border-[#0F3D2E] shadow-2xs'
                            : 'bg-slate-50 hover:bg-slate-100 text-slate-700 border-slate-200'
